        '@typescript-eslint/restrict-template-expressions': 'warn',
        '@typescript-eslint/no-misused-promises': 'warn',
        '@typescript-eslint/require-await': 'warn',
      },
    },
    {
      // e2e/ is deliberately plain CommonJS JS (require/module.exports),
      // matching playwright.config.js — the AGENTS.md TypeScript-only rule
      // is scoped to overrides/ only. The vendor base config
      // (@salesforce/pwa-kit-dev/configs/eslint/partials/base.js) applies
      // plugin:@typescript-eslint/recommended repo-wide with no files
      // scoping of its own, so no-var-requires fires here even though these
      // are plain .js files, not TypeScript.
      files: ['e2e/**/*.js'],
      rules: {
        '@typescript-eslint/no-var-requires': 'off',
      },
    },
    {
      // scripts/contentful/ is deliberately plain CommonJS JS (require/module.exports) —
      // same reasoning as the e2e/ override above: the vendor base config applies
      // plugin:@typescript-eslint/recommended repo-wide with no files scoping of its
