import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import * as React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { renderHook, waitFor } from '@testing-library/react';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import { markProductViewed, RECENTLY_VIEWED_SESSION_KEY, useRecentlyViewedGate } from './useRecentlyViewedGate';

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useCustomerType: vi.fn(),
}));

const mockUseCustomerType = vi.mocked(useCustomerType);

function mockCustomerType(isRegistered: boolean): void {
  mockUseCustomerType.mockReturnValue({
    customerType: isRegistered ? 'registered' : 'guest',
    isGuest: !isRegistered,
    isRegistered,
    isExternal: false,
  });
}

describe('markProductViewed', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    window.sessionStorage.clear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    window.sessionStorage.clear();
  });

  test('sets the session flag', () => {
    markProductViewed();
    expect(window.sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY)).not.toBeNull();
  });

  test('does not throw, and leaves no flag set, when sessionStorage.setItem throws', () => {
    vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
      throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
    });

    expect(() => markProductViewed()).not.toThrow();

    vi.restoreAllMocks();
    expect(window.sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY)).toBeNull();
  });
});

describe('useRecentlyViewedGate', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    window.sessionStorage.clear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    window.sessionStorage.clear();
  });

  test('no flag set, guest -> false', async () => {
    mockCustomerType(false);

    const { result } = renderHook(() => useRecentlyViewedGate());

    await waitFor(() => expect(result.current).toBe(false));
  });

  test('flag set (via markProductViewed), guest -> true', async () => {
    mockCustomerType(false);
    markProductViewed();

    const { result } = renderHook(() => useRecentlyViewedGate());

    await waitFor(() => expect(result.current).toBe(true));
  });

  test('no flag set, registered -> true', async () => {
    mockCustomerType(true);

    const { result } = renderHook(() => useRecentlyViewedGate());

    await waitFor(() => expect(result.current).toBe(true));
  });

  test('sessionStorage.getItem throwing -> false, no uncaught exception', async () => {
    mockCustomerType(false);
    vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
      throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
    });

    const { result } = renderHook(() => useRecentlyViewedGate());

    await waitFor(() => expect(result.current).toBe(false));
  });

  test('first render, before the effect has run -> false (SSR-safety)', () => {
    // Deliberately the least favourable case: registered AND the session flag already set, so
    // a hook that (incorrectly) resolved either signal synchronously during render — instead
    // of deferring both to the effect — would show `true` here instead of `false`.
    mockCustomerType(true);
    window.sessionStorage.setItem(RECENTLY_VIEWED_SESSION_KEY, 'true');

    function GateHarness() {
      return React.createElement('span', null, String(useRecentlyViewedGate()));
    }

    // react-dom/server's renderToStaticMarkup never runs `useEffect` bodies — this is the real
    // SSR guarantee, not a simulation of it — so this proves the hook's return value at the
    // exact moment SSR reproduces: before any effect has had a chance to run.
    const html = renderToStaticMarkup(React.createElement(GateHarness));

    expect(html).toBe('<span>false</span>');
  });
});

