```ts
import { useEffect, useState } from 'react';
import { useCustomerType } from '@salesforce/commerce-sdk-react';

export const RECENTLY_VIEWED_SESSION_KEY = 'zimm-recently-viewed';

export const markProductViewed = (): void => {
  try {
    sessionStorage.setItem(RECENTLY_VIEWED_SESSION_KEY, 'true');
  } catch {
    // Safari private-browsing mode (or any other sessionStorage failure) — degrade silently,
    // no flag gets set.
  }
};

export const useRecentlyViewedGate = (): boolean => {
  const { isRegistered } = useCustomerType();
  const [hasRecentlyViewed, setHasRecentlyViewed] = useState(false);

  useEffect(() => {
    let sessionFlagIsSet = false;
    try {
      sessionFlagIsSet = sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY) !== null;
    } catch {
      sessionFlagIsSet = false;
    }
    setHasRecentlyViewed(sessionFlagIsSet || isRegistered);
  }, [isRegistered]);

  return hasRecentlyViewed;
};
```
(Full JSDoc with `@returns` is in the file — trimmed here for brevity.) `isRegistered`'s source is cited to `@salesforce/retail-react-app/app/hooks/use-einstein.js:449`, which I independently verified myself via `grep` before writing the comment, not just trusted from the prompt.

**2. CREATE `/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/overrides/app/hooks/useRecentlyViewedGate.test.ts`** — 7 tests: the 5 mandated cases plus 2 bonus cases for `markProductViewed`'s own contract (sets the flag; doesn't throw when `setItem` throws). Uses `vi.mock('@salesforce/commerce-sdk-react', ...)` (matching the existing pattern in `_app/index.test.tsx`) and `renderHook`/`waitFor` from `@testing-library/react` (matching `useCountryConfig.test.ts`). The SSR case uses `react-dom/server`'s `renderToStaticMarkup` — a real SSR render, not a simulation — because React guarantees `useEffect` bodies never execute during server rendering, which is a stronger and more faithful proof than trying to catch `renderHook`'s `act()` before it flushes effects.

**3. MODIFY `/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/overrides/app/pages/product-detail/index.tsx`** — exactly 2 lines, confirmed by `git diff --stat`: `1 file changed, 2 insertions(+)`, 0 deletions:

